import static org.junit.Assert.*;

public class StringUtils_equals_TriageGen0Test {

    @Test
    public void testEquals_BothNull() {
        // Covers: if (cs1 == cs2) return true;
        assertTrue(StringUtils.equals(null, null));
    }

    @Test
    public void testEquals_SameInstance() {
        // Covers: if (cs1 == cs2) return true;
        String str = "test";
        assertTrue(StringUtils.equals(str, str));
    }

    @Test
    public void testEquals_FirstNull() {
        // Covers: if (cs1 == null || cs2 == null) return false;
        assertFalse(StringUtils.equals(null, "abc"));
    }

    @Test
    public void testEquals_SecondNull() {
        // Covers: if (cs1 == null || cs2 == null) return false;
        assertFalse(StringUtils.equals("abc", null));
    }

    @Test
    public void testEquals_ContentMatch() {
        // Covers: return cs1.equals(cs2);
        assertTrue(StringUtils.equals("abc", "abc"));
        assertTrue(StringUtils.equals(new StringBuilder("abc"), "abc"));
    }

    @Test
    public void testEquals_ContentMismatch() {
        // Covers: return cs1.equals(cs2);
        assertFalse(StringUtils.equals("abc", "def"));
    }

    @Test
    public void testEquals_EmptyStrings() {
        // Covers: return cs1.equals(cs2);
        assertTrue(StringUtils.equals("", ""));
        assertFalse(StringUtils.equals("", " "));
    }
}
